// Candidata v87: confirmação de bots no servidor antes de iniciar como conexões reais e privadas no servidor multiplayer existente.
// O motor de regras, o embaralhamento e o cálculo das rodadas são SEMPRE do servidor.
const BOT_NAMES=['Bruxa Carmesim','Velho Corvo','Dama Rubra','Lobo Negro','Monge Cinzento','Raposa Astuta','Cavaleiro Pálido','Druida Noturno','Coruja Sombria'];
const BOT_PREFIX='Bot · ';
const bots=new Map();
let botChangeBusy=false,botSelectionTouched=false,startPending=false,startingWithBots=false;
const botStoreKey=code=>'taverna-beta-bots-'+code;
const getStoredBots=code=>{try{const a=JSON.parse(store.get(botStoreKey(code))||'[]');return Array.isArray(a)?a.filter(b=>b&&typeof b.token==='string'&&typeof b.name==='string'&&b.name.startsWith(BOT_PREFIX)).slice(0,9):[]}catch{return []}};
const humanCountIn=members=>(members||[]).filter(p=>!p.isBot).length;
const botSlots=members=>Math.max(0,Math.min(9,10-humanCountIn(members)));
function areAllBotsReady(members){
 const entries=(members||[]).filter(p=>p.isBot);
 if(entries.length!==bots.size)return false;
 for(const bot of bots.values()){
  if(!bot.id||!bot.token||bot.socket?.readyState!==WebSocket.OPEN)return false;
  if(!entries.some(p=>p.id===bot.id&&p.online&&p.name===bot.name))return false;
 }
 return true;
}
function persistBots(){if(!room)return;store.set(botStoreKey(room),JSON.stringify([...bots.values()].filter(b=>b.token&&!b.removed).map(b=>({token:b.token,name:b.name}))));}
function stopBotTimer(bot){if(bot.timer){clearTimeout(bot.timer);bot.timer=null;}bot.scheduledKey='';}
function shutdownBots(remove=false){
 if(!remove)persistBots();
 for(const b of bots.values()){
  b.removed=true;stopBotTimer(b);clearTimeout(b.reconnectTimer);
  if(b.socket){try{if(remove&&b.socket.readyState===WebSocket.OPEN)b.socket.send(JSON.stringify({type:'leave'}));b.socket.close();}catch{}}
 }
 bots.clear();if(remove&&room)store.del(botStoreKey(room));
}
function botCardValid(card,g){return !!card&&(!!g.pendingSeven?['7','J'].includes(card.rank):card.rank==='J'||card.rank===g.top?.rank||card.suit===g.activeSuit);}
function decideBot(g){
 const hand=g.hand||[],cards=hand.filter(c=>botCardValid(c,g));
 if(cards.length&&hand.length===2&&!g.mauAnnouncements?.[g.turnPlayerId])return {type:'action',action:'mau',revision:g.revision};
 if(cards.length){
  const c=cards.find(c=>g.pendingSeven&&c.rank==='7')||cards.find(c=>c.rank!=='J')||cards[0];
  let suit;
  if(c.rank==='J'){
   const groups=new Map();for(const x of hand)if(x.id!==c.id)groups.set(x.suit,(groups.get(x.suit)||0)+1);
   suit=[...groups].sort((a,b)=>b[1]-a[1])[0]?.[0]||c.suit;
  }
  return {type:'action',action:'play',cardId:c.id,suit,revision:g.revision};
 }
 if(g.pendingSeven)return {type:'action',action:'take_seven',revision:g.revision};
 return {type:'action',action:g.drawn?'pass':'draw',revision:g.revision};
}
function scheduleBot(bot,message){
 if(bot.removed||!bot.id)return;
 const g=message.game;
 // Uma revanche reinicia a revisão: não confundir seu turno com uma jogada antiga.
 const startId=(message.events||[]).filter(e=>e?.type==='start'&&e.id).at(-1)?.id||null;
 if(startId&&bot.matchStartId!==startId){
  stopBotTimer(bot);bot.executedKey='';bot.matchStartId=startId;
 }
 if(g?.phase==='finished'||g?.phase==='game_over')bot.executedKey='';
 const allowed=g?.phase==='playing'&&g.turnPlayerId===bot.id&&!message.opa&&bot.socket?.readyState===WebSocket.OPEN;
 if(!allowed){stopBotTimer(bot);return;}
 const k=[bot.matchStartId||'partida',g.round,g.revision,g.turnPlayerId].join('/');
 if(bot.scheduledKey===k||bot.executedKey===k)return;
 stopBotTimer(bot);bot.scheduledKey=k;
 bot.timer=setTimeout(()=>{
  bot.timer=null;if(bot.removed||bot.socket?.readyState!==WebSocket.OPEN||bot.scheduledKey!==k)return;
  bot.executedKey=k;bot.scheduledKey='';
  try{bot.socket.send(JSON.stringify(decideBot(g)));}catch(e){console.warn('Taverna Bot',e);bot.executedKey='';}
 },3000+Math.floor(Math.random()*2001));
}
function connectBot(bot){
 if(!room||bot.removed)return;
 const code=room;
 const url=new URL(API.replace(/^http/,'ws')+'/api/room/'+code+'/ws');
 url.searchParams.set('name',bot.name);url.searchParams.set('bot','1');url.searchParams.set('ownerToken',token);if(bot.token)url.searchParams.set('token',bot.token);
 let sock;try{sock=new WebSocket(url)}catch(e){bot.error=e.message;message('Falha ao convocar '+bot.name+': '+e.message);return;}
 bot.socket=sock;bot.error='';
 sock.onmessage=e=>{
  if(bot.removed||bots.get(bot.name)!==bot||sock!==bot.socket)return;
  let m;try{m=JSON.parse(e.data)}catch{return;}
  if(m.type==='welcome'){
   bot.id=m.id;bot.token=m.token;bot.retry=0;persistBots();
  }else if(m.type==='state'){
   scheduleBot(bot,m);
  }else if(m.type==='error'){
   bot.error=m.message||'Ação recusada pelo servidor';
   console.warn('Bot',bot.name,m.message);
   // Uma jogada inválida não autoriza burlar o servidor. O próximo estado retoma a decisão.
   if(m.message?.includes('mesa mudou'))bot.executedKey='';
  }
 };
 sock.onerror=()=>{bot.error='Falha de conexão';console.warn('Conexão do bot não disponível:',bot.name)};
 sock.onclose=e=>{
  stopBotTimer(bot);
  if(bot.removed||bots.get(bot.name)!==bot||room!==code||sock!==bot.socket)return;
  if(e.code===4001){bot.removed=true;bots.delete(bot.name);persistBots();refreshReadyAfterBots();return;}
   if(e.code===4000||e.code===1008||e.code===1003||bot.retry>=7){
   bot.error='Desconectado ('+e.code+')';message('Não foi possível manter '+bot.name+' na sala. Use Convocar bots para tentar novamente.');return;
  }
  const pause=Math.min(14000,850*Math.pow(2,bot.retry++));
  bot.reconnectTimer=setTimeout(()=>connectBot(bot),pause);
 };
}
function addBot(n,entry){
 const name=entry?.name||BOT_PREFIX+BOT_NAMES[n];if(bots.has(name))return;
 const bot={name,token:entry?.token||'',id:null,removed:false,timer:null,scheduledKey:'',executedKey:'',matchStartId:null,socket:null,retry:0,reconnectTimer:null,error:''};
 bots.set(name,bot);connectBot(bot);
}
function restoreBots(){
 if(!room||uid!==hostId||bots.size)return;
 for(const entry of getStoredBots(room)){
  const ix=BOT_NAMES.findIndex(n=>entry.name===BOT_PREFIX+n);
  if(ix>=0)addBot(ix,entry);
 }
}
