 const editable=host&&(!m.game||m.game.phase==='finished'||m.game.phase==='game_over');
 panel.hidden=!host;
 btn.disabled=!editable||botChangeBusy||startingWithBots||startPending;
 sel.disabled=!editable||botChangeBusy||startingWithBots||startPending;
 const limit=botSlots(m.players),currentConnected=(m.players||[]).filter(p=>p.online&&bots.size&&[...bots.values()].some(b=>b.id===p.id)).length;
 for(const opt of sel.options){opt.disabled=Number(opt.value)>limit;opt.hidden=Number(opt.value)>limit;}
 if(!botChangeBusy&&!botSelectionTouched&&!startingWithBots)sel.value=String(Math.min(bots.size,limit));
 if(Number(sel.value)>limit)sel.value=String(limit);
