}
function waitForBots(desired,maxWait=14000){
 // Host só inicia quando cada conexão está na lista do SERVIDOR, e não
 // apenas aberta no navegador. Evita mesas que começam sem os bots escolhidos.
 return new Promise(resolve=>{
  const started=Date.now();
  const tick=()=>{
   if(!room||uid!==hostId){resolve(false);return;}
   if(bots.size===desired&&areAllBotsReady(players)){resolve(true);return;}
   if(Date.now()-started>maxWait){resolve(false);return;}
   setTimeout(tick,150);
  };tick();
 });
}
async function applyBots(){
 if(botChangeBusy||!room||uid!==hostId||game?.phase==='playing'||game?.phase==='scoring')return false;
 const desired=Number(el('onlineBotsDEV').value);
 const humans=humanCountIn(players);
 if(!Number.isInteger(desired)||desired<0||desired>9||desired+humans>10){message('Capacidade máxima: dez participantes no total, incluindo bots.');return false;}
 botChangeBusy=true;el('onlineSaveBotsDEV').disabled=true;
 try{
  for(let i=8;i>=desired;i--){
   const name=BOT_PREFIX+BOT_NAMES[i],bot=bots.get(name);if(!bot)continue;
   bot.removed=true;stopBotTimer(bot);clearTimeout(bot.reconnectTimer);
   try{
    if(bot.socket?.readyState===WebSocket.OPEN){
     // O servidor precisa processar "leave" antes do fechamento do WebSocket.
     bot.socket.send(JSON.stringify({type:'leave'}));
    }else bot.socket?.close();
   }catch{}
   bots.delete(name);
  }
  for(let i=0;i<desired;i++){
   const name=BOT_PREFIX+BOT_NAMES[i];
   const old=bots.get(name);
   if(!old){addBot(i);continue;}
   // Tentar novamente após queda/recusa, sem duplicar uma conexão já ativa.
   if(old.socket?.readyState!==WebSocket.OPEN&&old.socket?.readyState!==WebSocket.CONNECTING){
    clearTimeout(old.reconnectTimer);old.reconnectTimer=null;old.retry=0;connectBot(old);
   }
  }
  persistBots();
  if(desired)message('Convocando '+desired+' bots para a sala…');
  const ready=await waitForBots(desired);
  if(!ready){
   const bad=[...bots.values()].filter(b=>!b.id||b.socket?.readyState!==WebSocket.OPEN);
   for(const b of bad){clearTimeout(b.reconnectTimer);b.retry=0;if(b.socket?.readyState===WebSocket.CLOSED)connectBot(b);}
   message('Não foi possível confirmar todos os bots no servidor. A partida NÃO foi iniciada. Confira a conexão e tente novamente.');
  }else message(desired?'Bots confirmados no servidor e prontos para jogar.':'Bots removidos da sala.');
  return ready;
 }finally{
  botChangeBusy=false;botSelectionTouched=false;
  el('onlineBotsDEV').value=String(Math.min(bots.size,botSlots(players)));
  el('onlineSaveBotsDEV').disabled=false;
  // A última confirmação do servidor pode chegar durante a conexão;
  // reavaliar a prontidão depois que os WebSockets efetivamente entraram.
  refreshReadyAfterBots();
 }
}
el('onlineBotsDEV').addEventListener('change',()=>{botSelectionTouched=true;refreshReadyAfterBots();});
el('onlineSaveBotsDEV').addEventListener('click',applyBots);


function refreshReadyAfterBots(){
 const desired=Number(el('onlineBotsDEV').value)||0;
 const humanCount=humanCountIn(players),total=humanCount+desired;
 const host=!!uid&&uid===hostId;
 const canPrepare=host&&!game&&!startingWithBots&&!startPending&&!botChangeBusy&&
  desired>=0&&desired<=botSlots(players)&&total>=2&&total<=10&&
  players.filter(p=>!p.isBot).every(p=>p.online);
 const ready=bots.size===desired&&areAllBotsReady(players)&&players.every(p=>p.online);
 el('onlineStart').disabled=!canPrepare;
 el('onlineStart').classList.toggle('hidden',!!game);
 el('onlineStartHint').textContent=game?'Partida iniciada.':startPending?'Aguardando o início da partida no servidor…':startingWithBots?'Confirmando os bots no servidor…':host&&total<2?'Selecione ao menos um bot ou aguarde outro jogador.':!canPrepare?'Aguarde os jogadores se conectarem.':ready?'Mesa pronta: '+total+' participantes confirmados.':'Ao iniciar, a Taverna convocará os bots e confirmará sua entrada antes de começar.';
 botControls({game,players});
}
async function startWithBots(){
 if(startingWithBots||startPending||!room||uid!==hostId||game)return;
 startingWithBots=true;refreshReadyAfterBots();
 try{
  // Selecionar uma quantidade e tocar INICIAR agora basta; a convocação
  // nunca mais é opcional ou esquecida antes da partida.
  const desired=Number(el('onlineBotsDEV').value)||0;
  if(desired+humanCountIn(players)>10||desired+humanCountIn(players)<2){
   message('Para começar, escolha uma mesa de 2 a 10 participantes.');return;
  }
  const joined=await applyBots();
  if(!joined){message('Partida não iniciada: um ou mais bots não foram confirmados na sala.');return;}
  const actualBots=players.filter(p=>p.isBot);
  const expectedIds=new Set([...bots.values()].map(b=>b.id));
  if(actualBots.length!==desired||actualBots.some(p=>!expectedIds.has(p.id)||!p.online)||
     players.some(p=>!p.online)||players.length!==humanCountIn(players)+desired){
   message('Partida bloqueada: a lista real de participantes não corresponde à seleção.');return;
  }
  window.__tavOriginalOnline?.unlockAudio();
  if(send({type:'start'})){startPending=true;message('Todos os '+players.length+' participantes confirmados. Iniciando partida…');}
 }finally{startingWithBots=false;refreshReadyAfterBots();}
}

const eventIds=m.events||[];
