const newMatch=!!game&&m.game.phase==='playing'&&(
 game.phase==='finished'||game.phase==='game_over'||
 (m.game.revision<revision&&freshStart&&m.game.round===1));
if(newMatch){
 cancelOnlineEffects();lastRenderedRound=null;
